#!/usr/bin/env bash
set -euo pipefail
mkdir -p src
cat > Cargo.toml <<'EOF'
[package]
name = "game-stamina"
version = "0.1.0"
edition = "2024"

[dependencies]
bevy = "0.20.1"

[workspace]
EOF
cat > Cargo.lock <<'EOF'
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 4

[[package]]
name = "bevy"
version = "0.20.1"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "78a6c6136c38a50f3d20069adb99064636afcb109cbdf27a00a8c1742f5d630c"

[[package]]
name = "game-stamina"
version = "0.1.0"
dependencies = [
 "bevy",
]
EOF
cat > src/main.rs <<'EOF'
//! game-stamina: a Bevy prototype with a player square moved by the arrow keys.

use bevy::prelude::*;

/// Marks the entity the player controls.
#[derive(Component)]
struct Player;

/// Movement tunables.
#[derive(Resource)]
struct MoveSettings {
    /// Walking speed in pixels per second.
    walk_speed: f32,
}

impl Default for MoveSettings {
    fn default() -> Self {
        Self { walk_speed: 200.0 }
    }
}

/// Spawns the camera and the player and moves the player from keyboard input.
struct PlayerPlugin;

impl Plugin for PlayerPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<MoveSettings>()
            .add_systems(Startup, spawn_player)
            .add_systems(Update, move_player);
    }
}

fn spawn_player(mut commands: Commands) {
    commands.spawn(Camera2d);
    commands.spawn((
        Player,
        Sprite::from_color(Color::srgb(0.2, 0.7, 0.3), Vec2::splat(32.0)),
        Transform::from_xyz(0.0, 0.0, 0.0),
    ));
}

fn move_player(
    keys: Res<ButtonInput<KeyCode>>,
    time: Res<Time>,
    settings: Res<MoveSettings>,
    mut player: Single<&mut Transform, With<Player>>,
) {
    let mut direction = Vec2::ZERO;
    if keys.pressed(KeyCode::ArrowLeft) {
        direction.x -= 1.0;
    }
    if keys.pressed(KeyCode::ArrowRight) {
        direction.x += 1.0;
    }
    if keys.pressed(KeyCode::ArrowDown) {
        direction.y -= 1.0;
    }
    if keys.pressed(KeyCode::ArrowUp) {
        direction.y += 1.0;
    }
    let step = direction.normalize_or_zero() * settings.walk_speed * time.delta_secs();
    player.translation += step.extend(0.0);
}

fn main() {
    App::new()
        .add_plugins((DefaultPlugins, PlayerPlugin))
        .run();
}
EOF
printf 'target/\n' > .gitignore
git init -q
git add -A
git -c user.name=eval -c user.email=eval@example.invalid commit -q -m "initial fixture"
